def solve(intervals):
    if not intervals:
        return []
    # sort by start
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0][:]]
    for s, e in intervals[1:]:
        last = merged[-1]
        if s <= last[1]:  # overlap or touch
            last[1] = max(last[1], e)
        else:
            merged.append([s, e])
    return merged

