    Connectivity is 4-directional.
    Args:
        grid: List of list of ints (0 or 1).
    Returns:
        int count of islands.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
