def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each token is an integer or one of '+', '-', '*', '/'.
    Returns integer result, division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                # Python division truncates toward zero via int(a / b)
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

