def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Tokens are strings representing integers or the operators +, -, *, /.
    Division truncates toward zero as specified.
    """
    stack = []
    for t in tokens:
        # Number detection: allow negative integers
        if t.lstrip('-').isdigit():
            stack.append(int(t))
        else:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            elif t == '/':
                # Truncate toward zero
                res = int(a / b)
            else:
                raise ValueError('Invalid token')
            stack.append(res)
    return stack[0] if stack else 0

