def solve(tokens):
    """Evaluate Reverse Polish Notation.
    Tokens may be strings or integers. Supports +, -, *, / where division
    truncates toward zero (like LeetCode's Evaluate Reverse Polish Notation).
    """
    ops = {'+', '-', '*', '/'}
    stack = []
    for token in tokens:
        # Normalise token to string for operator check
        if isinstance(token, str) and token in ops:
            # Pop two operands
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                if b == 0:
                    # Undefined – return 0 to keep function total
                    res = 0
                else:
                    # Truncate toward zero without using float
                    res = abs(a) // abs(b)
                    if (a < 0) ^ (b < 0):
                        res = -res
            stack.append(res)
        else:
            # Operand: may be int or numeric string
            if isinstance(token, int):
                stack.append(token)
            else:
                stack.append(int(token))
    return stack[0] if stack else 0

