def solve(grid):
    """Count islands in a binary grid (batch 2).
    Uses DFS to explore connected components of 1s (4-directional).
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if i<0 or i>=rows or j<0 or j>=cols:
                continue
            if visited[i][j] or grid[i][j]==0:
                continue
            visited[i][j] = True
            stack.extend([(i-1,j),(i+1,j),(i,j-1),(i,j+1)])
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j]==1 and not visited[i][j]:
                count+=1
                dfs(i,j)
    return count

